    @Test("faulty")
    func faulty() async throws {
        let score: Score = try (await Gp8ImporterTest.prepareImporterWithFile("guitarpro8/faulty.gp")).readScore()
        let usedChannels: Set<Double> = Set<Double>()
        for t in score.tracks {
            TestGlobals.expect(Number.isNaN(t.playbackInfo.primaryChannel)).toBe(false)
            TestGlobals.expect(Number.isNaN(t.playbackInfo.secondaryChannel)).toBe(false)
            if t.playbackInfo.primaryChannel != SynthConstants.PercussionChannel {
                TestGlobals.expect(usedChannels.has(t.playbackInfo.primaryChannel)).toBe(false)
                TestGlobals.expect(usedChannels.has(t.playbackInfo.secondaryChannel)).toBe(false)
                usedChannels.add(t.playbackInfo.primaryChannel)
                usedChannels.add(t.playbackInfo.secondaryChannel)
            }
        }
    }

