    @Test("bank")
    func bank() async throws {
        let score: Score = try (await Gp8ImporterTest.prepareImporterWithFile("guitarpro8/bank.gp")).readScore()
        try TestGlobals.expect(score.tracks.jsElement(0).playbackInfo.program).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(0).playbackInfo.bank).toBe(0.0)
        try TestGlobals.expect(score.tracks.jsElement(1).playbackInfo.program).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(1).playbackInfo.bank).toBe(77.0)
        try TestGlobals.expect(score.tracks.jsElement(2).playbackInfo.program).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(2).playbackInfo.bank).toBe(256.0)
    }

    @Test("bank-change")
    func bankChange() async throws {
        let score: Score = try (await Gp8ImporterTest.prepareImporterWithFile("guitarpro8/bank-change.gp")).readScore()
        try TestGlobals.expect(score.tracks.jsElement(0).playbackInfo.program).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(0).playbackInfo.bank).toBe(0.0)
        try TestGlobals.expect(score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(0).automations.length).toBe(1.0)
        try TestGlobals.expect(score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(0).getAutomation(AutomationType.Instrument)?.value).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(0).automations.length).toBe(2.0)
        try TestGlobals.expect(score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(0).getAutomation(AutomationType.Instrument)?.value).toBe(25.0)
        try TestGlobals.expect(score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(0).getAutomation(AutomationType.Bank)?.value).toBe(256.0)
    }

