    @Test("custom-beaming")
    func customBeaming() async throws {
        let score: Score = try (await Gp8ImporterTest.prepareImporterWithFile("guitarpro8/custom-beaming.gp")).readScore()
        try TestGlobals.expect(score.masterBars.jsElement(0).beamingRules).toBeTruthy()
        try TestGlobals.expect(jsNonNull(score.masterBars.jsElement(0).beamingRules).groups.has(Duration.Eighth)).toBe(true)
        try TestGlobals.expect(jsNonNull(jsNonNull(score.masterBars.jsElement(0).beamingRules).groups.get(Duration.Eighth)).join(",")).toBe("2,2,2,2")
        try TestGlobals.expect(score.masterBars.jsElement(1).beamingRules == nil, "expected beamingRules of bar 1 to be undefined").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(1).actualBeamingRules === score.masterBars.jsElement(0).beamingRules, "actualBeamingRules of bar 1 incorrect").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(2).beamingRules == nil, "expected beamingRules of bar 2 to be undefined").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(2).actualBeamingRules === score.masterBars.jsElement(0).beamingRules, "actualBeamingRules of bar 1 incorrect").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(3).beamingRules == nil, "expected beamingRules of bar 3 to be undefined").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(3).actualBeamingRules === score.masterBars.jsElement(0).beamingRules, "actualBeamingRules of bar 1 incorrect").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(4).beamingRules == nil, "expected beamingRules of bar 4 to be undefined").toBe(true)
        try TestGlobals.expect(score.masterBars.jsElement(4).actualBeamingRules === score.masterBars.jsElement(0).beamingRules, "actualBeamingRules of bar 1 incorrect").toBe(true)
        try TestGlobals.expect(jsNonNull(score.masterBars.jsElement(5).beamingRules).groups.has(Duration.Eighth)).toBe(true)
        try TestGlobals.expect(jsNonNull(jsNonNull(score.masterBars.jsElement(5).beamingRules).groups.get(Duration.Eighth)).join(",")).toBe("4,4")
    }

